func reverse(n int) int {
    return reverseWith(n, 0)
}

func reverseWith(n, acc int) int {
    if n == 0 {
        return acc
    }
    return reverseWith(n/10, acc*10+n%10)
}

func digitStats(n int) (int, int) {
    if n < 10 {
        return 1, n
    }
    count, sum := digitStats(n/10)
    return count+1, sum+n%10
}

func main() {
    count, sum := digitStats(472)
    fmt.Println(count, sum)
    fmt.Println(digitStats(5))
}
